#!/usr/bin/env python3
# Generated by hermes-software-factory (scripts/factory-github-templates.py) from scripts/factory_types.py: do not edit here.
"""Issue and pull request types of the factory (ADR 0017): one definition, deterministic checks.

The definition lives in config/types.yaml. install.sh deploys it in githooks/checks.json under « issue-types », where the
intake, coordinator-guard, the pre-push hook and the gate read it. The generator (factory-github-templates.py) copies
this module and the definition into code-my-life/.github, whose « Conventions » job runs the same checks on every pull
request of a public repository: this module therefore only uses the standard library. Its messages are in French, like
the issues they describe: the owner and the agents read them.
"""
from __future__ import annotations

import json
import re
import unicodedata
from pathlib import Path

NO_RESPONSE = "_No response_"
CRITERION = re.compile(r"^[ \t]*(?:[-*+][ \t]+)?(?:\[[ xX]\][ \t]+)?\**C(\d+)\**[ \t]*[:.)-][ \t]*(.*)$", re.M)
TEST_LINE = re.compile(r"`[^`\s]+\.[A-Za-z0-9]+`[^\n]*?(?:«[^»]+»|\"[^\"\n]+\"|“[^”\n]+”)")
# A mockup: a claude.ai artifact, a file attached to the issue, or the demo of a branch of the
# organisation (the owner's decision of 2026-11-04: for factory-live's PR acceptance, the demo is the mockup).
MOCKUP = re.compile(r"https://claude\.ai/(?:code/)?artifact/[\w-]+"
                    r"|https://github\.com/user-attachments/(?:files/\d+/[^\s)]+\.html?|assets/[\w-]+)"
                    r"|https://github\.com/code-my-life/[\w.-]+/tree/[\w./-]+", re.I)
FIXES = re.compile(r"\b(?:fix(?:es|ed)?|close[sd]?|resolve[sd]?)\s+#(\d+)\b", re.I)
BRANCH = re.compile(r"^(?P<prefix>[a-z]+)/(?P<number>\d+)-(?P<slug>[a-z0-9]+(?:-[a-z0-9]+)*)$")
TITLE = re.compile(r"^(?P<prefix>[a-z]+): \S")
BRIEF_TYPE = re.compile(r"^-\s*type\s*:\s*`?([\w-]+)`?", re.M)
BRIEF_VERSION = re.compile(r"^-\s*version_bump\s*:\s*`?(\w+)", re.M)
BRIEF_NUMBER = re.compile(r"^#\s+[\w./-]*#(\d+)\b", re.M)
CRITERIA_FIELD = "criteres"


def load(path: str | Path) -> dict:
    """The definition, from its YAML source (repository, install.sh) or from a JSON file that holds it alone or under
    « issue-types » (githooks/checks.json)."""
    path = Path(path)
    if path.suffix in (".yaml", ".yml"):
        import yaml  # only the repository and install.sh read the YAML source

        data = yaml.safe_load(path.read_text(encoding="utf-8"))
    else:
        data = json.loads(path.read_text(encoding="utf-8"))
    return data if "fields" in data else (data.get("issue-types") or {})


def normalize(text: str) -> str:
    """A heading compared without case, accents, typographic apostrophes or extra spaces."""
    text = unicodedata.normalize("NFKD", text.replace("’", "'"))
    text = "".join(c for c in text if not unicodedata.combining(c))
    return re.sub(r"\s+", " ", text).strip(" *:#").lower()


def sections(body: str, level: int) -> dict[str, str]:
    """The sections of a body by normalized heading: level 3 for an issue (issue forms write « ### <label> »), level 2
    for a pull request. The first section of a given name wins."""
    body = body or ""
    heads = list(re.finditer(rf"^{'#' * level}[ \t]+(.+?)[ \t]*#*[ \t]*$", body, re.M))
    out: dict[str, str] = {}
    for i, m in enumerate(heads):
        end = heads[i + 1].start() if i + 1 < len(heads) else len(body)
        out.setdefault(normalize(m.group(1)), body[m.end():end].strip())
    return out


def is_blank(text: str | None) -> bool:
    text = (text or "").strip()
    return not text or text == NO_RESPONSE or re.fullmatch(r"(?:[-*+]\s*)?(?:…|\.\.\.)?", text) is not None


def criteria(text: str | None) -> dict[int, str]:
    """The numbered criteria of a section: number -> text (the first line of each)."""
    out: dict[int, str] = {}
    for m in CRITERION.finditer(text or ""):
        out.setdefault(int(m.group(1)), m.group(2).strip())
    return out


def criteria_problem(text: str) -> str | None:
    ids = [int(m.group(1)) for m in CRITERION.finditer(text or "")]
    if not ids:
        return "aucun critère numéroté : une ligne par critère, « - C1 : … »"
    if ids != list(range(1, len(ids) + 1)):
        return f"critères mal numérotés ({', '.join(f'C{i}' for i in ids)}) : C1, C2, C3… sans trou ni doublon"
    empty = [f"C{n}" for n, said in criteria(text).items() if is_blank(said)]
    if empty:
        return "critères sans contenu : " + ", ".join(empty)
    return None


def tests_problem(text: str) -> str | None:
    if TEST_LINE.search(text or ""):
        return None
    return "aucun test nommé : une ligne par test, le fichier entre accents graves et le nom exact entre « »"


def mockup_problem(text: str) -> str | None:
    if MOCKUP.search(text or ""):
        return None
    return ("aucun lien de maquette : l'artifact claude.ai validé, le fichier HTML joint à l'issue, "
            "ou la démo d'une branche (github.com/code-my-life/<dépôt>/tree/<branche>)")


CHECKS = {"criteria": criteria_problem, "tests": tests_problem, "mockup": mockup_problem}


def required_fields(t: dict) -> list[str]:
    """The fields of a type an issue must fill; « ? » marks an optional one."""
    return [f for f in t["fields"] if not f.endswith("?")]


def type_names(d: dict) -> str:
    return ", ".join(t["name"] for t in d["types"].values())


def type_of_labels(labels, d: dict) -> tuple[str | None, str | None]:
    """(type, problem) from the labels of an issue: exactly one type label."""
    by_label = {t["label"]: key for key, t in d["types"].items()}
    found = sorted({by_label[name] for name in labels if name in by_label})
    if not found:
        return None, (f"type manquant : crée l'issue depuis un modèle ({type_names(d)}) ou pose un seul label "
                      "« type:… »")
    if len(found) > 1:
        return None, "plusieurs types (" + ", ".join(d["types"][k]["label"] for k in found) + ") : garde un seul label « type:… »"
    return found[0], None


def issue_problems(key: str, body: str, d: dict) -> list[str]:
    """What an issue of this type lacks before it can be built: absent or empty required sections, criteria that are not
    numbered C1, C2…, no named test, no mockup link."""
    found = sections(body, 3)
    problems = []
    for fid in required_fields(d["types"][key]):
        field = d["fields"][fid]
        text = found.get(normalize(field["label"]))
        if text is None:
            problems.append(f"section « {field['label']} » absente")
        elif is_blank(text):
            problems.append(f"section « {field['label']} » vide")
        elif field.get("check") in CHECKS:
            why = CHECKS[field["check"]](text)
            if why:
                problems.append(f"« {field['label']} » : {why}")
    return problems


def issue_criteria(body: str, d: dict) -> dict[int, str]:
    return criteria(sections(body, 3).get(normalize(d["fields"][CRITERIA_FIELD]["label"])))


def skipped_branch(branch: str, d: dict) -> bool:
    return any(branch.startswith(p) for p in d.get("branch-skip") or [])


def branch_parts(branch: str) -> tuple[str, int] | None:
    m = BRANCH.match(branch or "")
    return (m.group("prefix"), int(m.group("number"))) if m else None


def type_of_prefix(prefix: str, d: dict) -> str | None:
    return next((key for key, t in d["types"].items() if t.get("prefix") == prefix), None)


def prefixes(d: dict) -> list[str]:
    return [t["prefix"] for t in d["types"].values() if t.get("prefix")]


def branch_problem(key: str | None, branch: str, number: int | None, d: dict) -> str | None:
    """None when the branch reads « <prefix of the type>/<issue number>-<subject> »; without a type, any prefix of a
    type is accepted."""
    allowed = [d["types"][key].get("prefix")] if key else prefixes(d)
    if key and not allowed[0]:
        return f"un {d['types'][key]['name']} ne part pas en branche : il se termine sans PR"
    shown = f"{allowed[0]}/{number if number is not None else '<n°>'}-<sujet>" if key else "<préfixe>/<n°>-<sujet>"
    parts = branch_parts(branch)
    if not parts or parts[0] not in allowed:
        return (f"branche « {branch} » : « {shown} » attendu, en minuscules, chiffres et tirets"
                + ("" if key else f" ; préfixes : {', '.join(allowed)}"))
    if number is not None and parts[1] != number:
        return f"branche « {branch} » : numéro {number} attendu, celui de l'issue"
    return None


def pr_problems(key: str, title: str, body: str, number: int, wanted: dict[int, str] | list[int], d: dict) -> list[str]:
    """What a pull request of this type lacks: title prefix, « Fixes #n », the sections of the type, and one proof line per
    criterion of the issue (« - C1 : <test, mesure, capture> » or « non prouvé »)."""
    t = d["types"][key]
    if not t.get("prefix"):
        return [f"un {t['name']} se termine sans PR"]
    return [p for p in [pr_title_problem(key, title, d)] if p] + pr_body_problems(key, body, number, wanted, d)


def pr_title_problem(key: str, title: str, d: dict) -> str | None:
    """The title of a pull request of this type reads « <prefix>: <titre> »."""
    t = d["types"][key]
    m = TITLE.match(title or "")
    if not m or m.group("prefix") != t["prefix"]:
        return f"titre « {title} » : « {t['prefix']}: <titre> » attendu pour un type {t['name']}"
    return None


def pr_body_problems(key: str, body: str, number: int, wanted: dict[int, str] | list[int], d: dict) -> list[str]:
    """What the text of a pull request of this type lacks: « Fixes #n », its sections, one proof line per criterion."""
    t = d["types"][key]
    problems = []
    if number not in {int(x) for x in FIXES.findall(body or "")}:
        problems.append(f"texte : « Fixes #{number} » manquant")
    found = sections(body, 2)
    for name in [*d.get("pr-sections", []), *t.get("pr-sections", [])]:
        text = found.get(normalize(name))
        if text is None:
            problems.append(f"texte : section « ## {name} » absente")
        elif is_blank(text):
            problems.append(f"texte : section « ## {name} » vide")
    proofs = criteria(found.get(normalize("Critères")))
    missing = [f"C{n}" for n in sorted(wanted) if is_blank(proofs.get(n))]
    if missing:
        problems.append("critères sans ligne de preuve dans « ## Critères » : " + ", ".join(missing)
                        + " (« - C1 : <test, mesure ou capture> », ou « non prouvé »)")
    return problems


def brief_type(body: str) -> str | None:
    m = BRIEF_TYPE.search(body or "")
    return m.group(1) if m else None


def brief_number(body: str) -> int | None:
    m = BRIEF_NUMBER.search(body or "")
    return int(m.group(1)) if m else None


def brief_criteria(body: str) -> dict[int, str]:
    """The criteria of a brief, in its « ## Critères d'acceptation » section."""
    return criteria(sections(body, 2).get(normalize("Critères d'acceptation")))


def brief_problems(key: str, body: str, d: dict) -> list[str]:
    """What an implementation brief of this type lacks for the gate: the branch, the version bump and the criteria."""
    t = d["types"].get(key)
    if not t:
        return [f"type « {key} » inconnu ; types : {', '.join(d['types'])}"]
    if not t.get("prefix"):
        return [f"un {t['name']} ne donne pas de carte d'implémentation : crée une carte « diagnostic » (lecture seule)"]
    problems = []
    branch = re.search(r"^-\s*branch_name\s*:\s*`?([\w./-]+)`?", body or "", re.M)
    why = branch_problem(key, branch.group(1) if branch else "", brief_number(body), d)
    if why:
        problems.append(why)
    version = BRIEF_VERSION.search(body or "")
    if not version or version.group(1) != t["version"]:
        problems.append(f"version_bump : « {t['version']} » attendu pour un type {t['name']}")
    if not brief_criteria(body):
        problems.append("aucun critère numéroté dans « ## Critères d'acceptation » (« - [ ] C1 : … », repris de l'issue)")
    return problems
